export default function collectSentimentDetails({ issues, previousState, issue }) {
  const state =
    previousState === null ? { index: 0, issues: [] } : JSON.parse(JSON.stringify(previousState));
  if (
    !Array.isArray(issues) ||
    issues.length > 50 ||
    new Set(issues.map((i) => i.id)).size !== issues.length
  )
    throw new Error("Expected the source first50 unique Linear issues.");
  if (previousState !== null) {
    const expected = issues[state.index];
    if (
      !expected ||
      !issue ||
      issue.id !== expected.id ||
      !Array.isArray(issue.comments?.nodes) ||
      issue.comments.nodes.length > 50
    )
      throw new Error("Linear issue detail does not match the selected issue.");
    for (const k of ["id", "identifier", "title", "createdAt", "updatedAt"])
      if (typeof issue[k] !== "string" || !issue[k])
        throw new Error("Linear issue metadata is incomplete.");
    const text = issue.comments.nodes
      .map((c) => {
        if (typeof c.body !== "string" || typeof c.createdAt !== "string")
          throw new Error("Linear comment content is incomplete.");
        return (
          (c.user?.displayName ?? c.user?.name ?? "Unknown author") +
          " commented on " +
          c.createdAt +
          ":\n" +
          c.body
        );
      })
      .join("---\n");
    if (!text.trim())
      throw new Error("The source Information Extractor needs nonempty comment text.");
    state.issues.push({
      id: issue.id,
      identifier: issue.identifier,
      title: issue.title,
      url: issue.url,
      createdAt: issue.createdAt,
      updatedAt: issue.updatedAt,
      assignee: issue.assignee ?? null,
      commentText: text,
    });
    state.index++;
  }
  return {
    state,
    more: state.index < issues.length,
    issueId: issues[state.index]?.id ?? "unused-complete",
  };
}

