export function parseSentimentText(text) {
  if (typeof text !== "string") throw new Error("Sentiment completion is not text.");
  const result = JSON.parse(text.trim().replace(/^```(?:json)?\s*|\s*```$/g, ""));
  if (
    !result ||
    typeof result !== "object" ||
    Array.isArray(result) ||
    !["positive", "negative", "neutral"].includes(result.sentiment) ||
    (result.sentimentSummary !== undefined && typeof result.sentimentSummary !== "string") ||
    Object.keys(result).some((k) => !["sentiment", "sentimentSummary"].includes(k))
  )
    throw new Error(
      "Expected sentiment positive/negative/neutral and optional text sentimentSummary.",
    );
  return { sentiment: result.sentiment, sentimentSummary: result.sentimentSummary ?? "" };
}
export default function collectIssueSentiments({
  issues,
  previousState,
  response,
  formatInstructions,
  systemPrompt,
  repairTemplate,
}) {
  const state =
    previousState === null
      ? { index: 0, drafts: [], repair: false, repairPrompt: "" }
      : JSON.parse(JSON.stringify(previousState));
  if (previousState !== null) {
    if (state.index >= issues.length) throw new Error("Unexpected sentiment completion.");
    try {
      const result = parseSentimentText(response);
      const { commentText, ...metadata } = issues[state.index];
      state.drafts.push({ ...metadata, ...result });
      state.index++;
      state.repair = false;
      state.repairPrompt = "";
    } catch (error) {
      if (state.repair) throw new Error("Sentiment format repair failed: " + error.message);
      state.repair = true;
      const replacements = {
        instructions: formatInstructions,
        completion: String(response),
        error: error.message,
      };
      state.repairPrompt = repairTemplate.replace(
        /\{(instructions|completion|error)\}/g,
        (_, key) => replacements[key],
      );
    }
  }
  const next = issues[state.index];
  return {
    state,
    more: state.index < issues.length,
    repair: state.repair,
    prompt: state.repair
      ? state.repairPrompt
      : systemPrompt +
        "\n" +
        formatInstructions +
        "\n\n" +
        (next?.commentText ?? "No pending issue."),
  };
}

