export default function collectSentimentUpserts({
  drafts,
  previousState,
  records,
  offset,
  body,
  statusCode,
  bodyEncoding,
}) {
  const state =
    previousState === null
      ? {
          index: 0,
          saved: [],
          phase: "lookup",
          records: [],
          offset: null,
          seenOffsets: [],
          writeBody: null,
        }
      : JSON.parse(JSON.stringify(previousState));
  if (previousState !== null) {
    const draft = drafts[state.index];
    if (!draft) throw new Error("Unexpected sentiment save response.");
    if (state.phase === "lookup") {
      if (!Array.isArray(records)) throw new Error("Airtable lookup is not a record array.");
      state.records.push(...records);
      if (state.records.length > 1)
        throw new Error("Issue ID must uniquely identify an Airtable row.");
      if (offset !== null) {
        if (typeof offset !== "string" || !offset || state.seenOffsets.includes(offset))
          throw new Error("Airtable lookup cursor did not advance.");
        state.offset = offset;
        state.seenOffsets.push(offset);
      } else {
        const prior = state.records[0]?.fields?.["Current Sentiment"];
        if (prior !== undefined && typeof prior !== "string")
          throw new Error("Previous sentiment is not a text/select value.");
        state.writeBody = {
          performUpsert: { fieldsToMergeOn: ["Issue ID"] },
          records: [
            {
              fields: {
                "Issue ID": draft.identifier,
                "Previous Sentiment": prior ?? "N/A",
                "Current Sentiment": draft.sentiment[0].toUpperCase() + draft.sentiment.slice(1),
                Summary: draft.sentimentSummary,
                "Issue Title": draft.title,
                "Issue Created": draft.createdAt,
                "Issue Updated": draft.updatedAt,
                Assigned: draft.assignee?.name ?? "",
              },
            },
          ],
          typecast: false,
        };
        state.phase = "upsert";
        state.offset = null;
      }
    } else {
      if (
        statusCode < 200 ||
        statusCode >= 300 ||
        bodyEncoding !== null ||
        !body ||
        !Array.isArray(body.records) ||
        body.records.length !== 1 ||
        typeof body.records[0].id !== "string" ||
        !body.records[0].id.trim() ||
        body.records[0].fields?.["Issue ID"] !== draft.identifier ||
        body.records[0].fields?.["Current Sentiment"] !==
          state.writeBody.records[0].fields["Current Sentiment"]
      )
        throw new Error("Airtable did not confirm the expected sentiment upsert.");
      state.saved.push({
        issueId: draft.id,
        identifier: draft.identifier,
        recordId: body.records[0].id,
        currentSentiment: body.records[0].fields["Current Sentiment"],
      });
      state.index++;
      state.phase = "lookup";
      state.records = [];
      state.offset = null;
      state.seenOffsets = [];
      state.writeBody = null;
    }
  }
  const next = drafts[state.index];
  return {
    state,
    lookup: !!next && state.phase === "lookup",
    upsert: !!next && state.phase === "upsert",
    filterByFormula: next
      ? "{Issue ID} = '" + next.identifier.replace(/\\/g, "\\\\").replace(/'/g, "\\'") + "'"
      : "FALSE()",
    offset: state.offset,
    body: state.writeBody ?? {},
    count: state.saved.length,
    saved: state.saved,
    report: { kind: "sentiment-analysis", count: state.saved.length, saved: state.saved },
  };
}

