export function escapeSentimentSlack(text) {
  return text.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
}
export default function prepareSentimentNotices({ events, issueUrlBase }) {
  if (
    !Array.isArray(events) ||
    typeof issueUrlBase !== "string" ||
    !/^https:\/\/linear\.app\/[a-zA-Z0-9_-]+\/issue\/$/.test(issueUrlBase)
  )
    throw new Error("Configure the Linear organization issue URL.");
  const seen = new Set(),
    transitions = [];
  for (const event of events) {
    const f = event.fields;
    if (!f || typeof f !== "object") throw new Error("Airtable event fields are missing.");
    if (f["Previous Sentiment"] === "Negative" || f["Current Sentiment"] !== "Negative") continue;
    for (const key of ["Issue ID", "Issue Title", "Last Modified"])
      if (typeof f[key] !== "string" || !f[key])
        throw new Error("Negative transition metadata is incomplete.");
    if (
      !/^\d{4}-\d\d-\d\dT/.test(f["Last Modified"]) ||
      !Number.isFinite(Date.parse(f["Last Modified"]))
    )
      throw new Error("Last Modified must be an Airtable time field.");
    if (f.Summary !== undefined && typeof f.Summary !== "string")
      throw new Error("Airtable summary is not text.");
    const key = f["Issue ID"] + ":" + f["Last Modified"];
    if (seen.has(key)) continue;
    seen.add(key);
    transitions.push({ ...f });
  }
  const chunks = [],
    header = {
      type: "section",
      text: {
        type: "mrkdwn",
        text: ":rotating_light: The following issues transitioned to Negative Sentiment",
      },
    },
    divider = { type: "divider" };
  let blocks = [header, divider];
  for (const f of transitions) {
    const url = issueUrlBase + encodeURIComponent(f["Issue ID"]),
      link = "*<" + url + "|" + escapeSentimentSlack(f["Issue ID"]) + ">* ";
    if (link.length > 3000) throw new Error("Linear issue link exceeds one Slack section.");
    let segment = link;
    const parts = [];
    for (const character of f["Issue Title"] + "\n" + (f.Summary ?? "")) {
      const token = escapeSentimentSlack(character);
      if (segment.length + token.length > 3000) {
        parts.push(segment);
        segment = "";
      }
      segment += token;
    }
    if (segment) parts.push(segment);
    for (const text of parts) {
      if (blocks.length === 50) {
        chunks.push({ blocks });
        blocks = [header, divider];
      }
      blocks.push({ type: "section", text: { type: "mrkdwn", text } });
    }
  }
  if (blocks.length > 2) chunks.push({ blocks });
  return {
    messages: chunks.map((chunk, i) => ({
      ...chunk,
      text:
        transitions.length +
        " issues transitioned to Negative Sentiment" +
        (chunks.length > 1 ? " (" + (i + 1) + "/" + chunks.length + ")" : ""),
    })),
    count: transitions.length,
  };
}

