export default function collectSentimentNotifications({
  messages,
  transitionCount,
  previousState,
  ts,
  channel,
}) {
  const state =
    previousState === null ? { index: 0, receipts: [] } : JSON.parse(JSON.stringify(previousState));
  if (previousState !== null) {
    if (
      state.index >= messages.length ||
      typeof ts !== "string" ||
      !ts ||
      typeof channel !== "string" ||
      !channel
    )
      throw new Error("Slack did not confirm the sentiment notification.");
    state.receipts.push({ ts, channel });
    state.index++;
  }
  const next = messages[state.index];
  return {
    state,
    more: state.index < messages.length,
    blocks: next?.blocks ?? null,
    text: next?.text ?? "No negative transitions.",
    notifications: state.receipts,
    transitionCount,
    messageCount: state.receipts.length,
    report: {
      kind: "negative-transition-notifications",
      transitionCount,
      messageCount: state.receipts.length,
      notifications: state.receipts,
    },
  };
}
